import express from 'express';
import { z } from 'zod';
import { requireAuth } from '../auth/middleware.js';
import { paginate, pageCount } from '../utils/paginate.js';
import { truncate } from '../utils/strings.js';

const MAX_TITLE = 120;
const MAX_BODY = 10_000;

const TAGS_ERROR = 'tags must be a list of strings';

export const noteSchema = z.object(
  {
    title: z
      .string({ error: 'title is required' })
      .refine(s => s.trim().length > 0, { error: 'title is required', abort: true })
      .max(MAX_TITLE, { error: `title must be at most ${MAX_TITLE} characters` }),
    body: z
      .string({ error: 'body must be a string' })
      .max(MAX_BODY, { error: `body must be at most ${MAX_BODY} characters` })
      .optional(),
    tags: z.array(z.string({ error: TAGS_ERROR }), { error: TAGS_ERROR }).optional(),
  },
  { error: 'request body must be a JSON object' },
);

/** Returns `{ data }` on success or `{ errors: string[] }` on failure. */
function validateNote(input) {
  const result = noteSchema.safeParse(input);
  if (result.success) return { data: result.data };
  return { errors: [...new Set(result.error.issues.map(issue => issue.message))] };
}

