import { test, before, after } from 'node:test';
import assert from 'node:assert/strict';
import { createApp } from '../src/server.js';
import { createStore } from '../src/store.js';
import { createSession } from '../src/auth/middleware.js';

let server;
let baseUrl;
let store;
const token = createSession('tester');

before(async () => {
  store = createStore();
  server = createApp(store).listen(0);
  await new Promise(resolve => server.once('listening', resolve));
  baseUrl = `http://127.0.0.1:${server.address().port}`;
});

after(() => new Promise(resolve => server.close(resolve)));

function postNote(payload) {
  return fetch(`${baseUrl}/notes`, {
    method: 'POST',
    headers: { 'content-type': 'application/json', authorization: `Bearer ${token}` },
    body: JSON.stringify(payload),
  });
}

test('creates a note with a valid body', async () => {
  const res = await postNote({ title: 'groceries', body: 'milk', tags: ['home'] });
  assert.equal(res.status, 201);
  const note = await res.json();
  assert.equal(note.title, 'groceries');
  assert.equal(note.body, 'milk');
  assert.deepEqual(note.tags, ['home']);
});

test('applies defaults for optional fields', async () => {
  const res = await postNote({ title: 'just a title' });
  assert.equal(res.status, 201);
  const note = await res.json();
  assert.equal(note.body, '');
  assert.deepEqual(note.tags, []);
});

test('ignores unknown fields such as id', async () => {
  const res = await postNote({ title: 'sneaky', id: 999, createdAt: 'yesterday' });
  assert.equal(res.status, 201);
  const note = await res.json();
  assert.notEqual(note.id, 999);
  assert.notEqual(note.createdAt, 'yesterday');
});

const invalidCases = [
  ['missing title', { body: 'x' }, ['title is required']],
  ['non-string title', { title: 42 }, ['title is required']],
  ['blank title', { title: '   ' }, ['title is required']],
  ['blank overlong title', { title: ' '.repeat(121) }, ['title is required']],
  ['overlong title', { title: 'a'.repeat(121) }, ['title must be at most 120 characters']],
  ['non-string body', { title: 't', body: 5 }, ['body must be a string']],
  ['null body', { title: 't', body: null }, ['body must be a string']],
  ['overlong body', { title: 't', body: 'a'.repeat(10_001) }, ['body must be at most 10000 characters']],
  ['non-array tags', { title: 't', tags: 'a,b' }, ['tags must be a list of strings']],
  ['non-string tags', { title: 't', tags: ['ok', 1, 2] }, ['tags must be a list of strings']],
  ['multiple problems', { body: 1, tags: {} }, ['title is required', 'body must be a string', 'tags must be a list of strings']],
  ['array payload', [], ['request body must be a JSON object']],
];

for (const [name, payload, expected] of invalidCases) {
  test(`rejects ${name}`, async () => {
    const before = store.count();
    const res = await postNote(payload);
    assert.equal(res.status, 400);
    assert.deepEqual(await res.json(), { errors: expected });
    assert.equal(store.count(), before);
  });
}

test('still requires auth before validating', async () => {
  const res = await fetch(`${baseUrl}/notes`, {
    method: 'POST',
    headers: { 'content-type': 'application/json' },
    body: JSON.stringify({}),
  });
  assert.equal(res.status, 401);
});

